-- paper-warm: light, warm, minimal. Generated by tweak-my-term.
local wezterm = require 'wezterm'
local config = wezterm.config_builder()

local paper, ink, accent = '#F5EFE1', '#3B3228', '#B5532E'

config.default_prog = { 'powershell.exe', '-NoLogo' }

config.colors = {
  foreground = ink,
  background = paper,
  cursor_bg = accent,
  cursor_border = accent,
  cursor_fg = paper,
  selection_bg = '#E4D8BC',
  selection_fg = ink,
  ansi = {
    '#3B3228', '#A8302B', '#4F6B2F', '#8A6410',
    '#3A5F8A', '#7A4A7E', '#2F6F6B', '#756A58',
  },
  brights = {
    '#74685A', '#AE4A27', '#53722F', '#80590C',
    '#4468A0', '#8A5690', '#2A716C', '#5E5444',
  },
  tab_bar = {
    background = paper,
    new_tab = { bg_color = paper, fg_color = '#74685A' },
  },
}
config.bold_brightens_ansi_colors = false

config.font = wezterm.font_with_fallback {
  'JetBrains Mono',
  'Symbols Nerd Font Mono',
}
config.font_size = 12
config.line_height = 1.2

config.window_padding = { top = 20, right = 28, bottom = 20, left = 28 }
config.initial_cols = 110
config.initial_rows = 30
config.enable_scroll_bar = false
config.default_cursor_style = 'SteadyBar'
config.window_background_opacity = 1.0

-- One clean window: paper-coloured frame, no tab chrome beyond the window buttons.
config.window_decorations = 'INTEGRATED_BUTTONS|RESIZE'
config.use_fancy_tab_bar = true
config.hide_tab_bar_if_only_one_tab = false
config.show_new_tab_button_in_tab_bar = false
config.window_frame = {
  font = wezterm.font 'JetBrains Mono',
  font_size = 10,
  active_titlebar_bg = paper,
  inactive_titlebar_bg = paper,
}
config.window_close_confirmation = 'NeverPrompt'
config.check_for_updates = false

return config
